	<section class="mx-auto max-w-4xl px-4 py-20 sm:px-6 lg:px-8 lg:py-28"><h2 class="text-3xl font-bold text-white sm:text-4xl">سؤالات متداول توسعه ووکامرس</h2><div class="mt-10 divide-y divide-white/10"><?php foreach ( $faqs as $question => $answer ) : ?><details class="group py-5"><summary class="flex cursor-pointer list-none items-center justify-between gap-5 font-bold text-white"><?php echo esc_html( $question ); ?><span class="text-xl text-amber-400 transition group-open:rotate-45" aria-hidden="true">+</span></summary><p class="mt-4 text-sm leading-8 text-neutral-400"><?php echo esc_html( $answer ); ?></p></details><?php endforeach; ?></div></section>

